			const touches = e.touches;
			if ( touches && touches.length ) {	
				_mx = touches[0].clientX;
				_my = touches[0].clientY;
			} else {
				_mx = e.clientX;
				_my = e.clientY;
			} 
	
            
            TweenMax.to( $cursor, 0.2, {
                left: _mx,
                top: _my,
                ease: Power4.easeOut
            });


            //
            let timer;
            
            $cursor.addClass( 'is-moving' );
            clearTimeout(timer);

            timer = setTimeout( function() {
                $cursor.removeClass( 'is-moving' );
            }, 300 );
            
            
