            /*
             * Portfolio and navigation hover effects.
             * These helpers only affect hover visuals; click behavior stays unchanged.
             */
            function disposeWorksEnergyConnections() {
                if (!worksEnergyGroup) return;

                worksEnergyGroup.children.forEach(function (child) {
                    if (child.geometry && child.geometry.dispose) child.geometry.dispose();
                    if (child.material) {
                        if (Array.isArray(child.material)) {
                            child.material.forEach(function (material) { material.dispose(); });
                        } else if (child.material.dispose) {
                            child.material.dispose();
                        }
                    }
                });

                if (worksEnergyGroup.parent) worksEnergyGroup.parent.remove(worksEnergyGroup);
                worksEnergyGroup = null;
                worksEnergyConnections = [];
                worksEnergyNet = null;
            }

            function showWorksEnergyConnections(stone) {
                if (!stone || !modalObjSubStoneForWorks) return;

                disposeWorksEnergyConnections();

                worksEnergyGroup = new THREE.Object3D();
                worksEnergyGroup.name = 'works-energy-connections';
                worksEnergyGroup.visible = true;
                scene.add(worksEnergyGroup);

                const cfg = WORKS_NET;
                const rand = function (min, max) { return min + Math.random() * (max - min); };
                const randInt = function (range) { return Math.floor(rand(range[0], range[1] + 1)); };
                const randVec = function (scale) {
                    return new THREE.Vector3(rand(-1, 1), rand(-1, 1), rand(-1, 1)).multiplyScalar(scale);
                };

                const stoneCenter = stone.getWorldPosition(new THREE.Vector3());
                const portfolioCenter = modalObjSubStoneForWorks.getWorldPosition(new THREE.Vector3());
                const bounds = new THREE.Box3().setFromObject(stone);
                const sphere = bounds.getBoundingSphere(new THREE.Sphere());
                // Keep the strand origin on the visible stone surface (same idea as before).
                const sourceCenterOffset = sphere.center.clone().sub(stoneCenter);
                const sourceRaycaster = new THREE.Raycaster();

                worksEnergyUniforms.uDepthRef.value = Math.max(camera.position.distanceTo(stoneCenter), 1);

                // ---------- palette ----------
                const C = [0x35eaff, 0x438dff, 0x9b70ff, 0xff69c8].map(function (hex) { return new THREE.Color(hex); });
                const gradients = {
                    primary  : [C[0], C[1], C[2]],     // cyan -> blue -> violet   (stone -> hub)
                    secondary: [C[2], C[3]],           // violet -> pink           (hub -> leaf)
                    cross    : [C[1], C[3]]            // blue -> pink
                };
                const sampleGradient = function (stops, t) {
                    const gp = t * (stops.length - 1);
                    const i = Math.min(Math.floor(gp), stops.length - 2);
                    return stops[i].clone().lerp(stops[i + 1], gp - i);
                };

                // ---------- 1. nodes ----------
                const space = cfg.space;
                const clampToSpace = function (p) {
                    p.x = Math.max(portfolioCenter.x - space.x * 1.05, Math.min(portfolioCenter.x + space.x * 1.05, p.x));
                    p.y = Math.max(portfolioCenter.y - space.y * 1.05, Math.min(portfolioCenter.y + space.y * 1.05, p.y));
                    p.z = Math.max(portfolioCenter.z - space.z * 1.05, Math.min(portfolioCenter.z + space.z * 1.05, p.z));
                    return p;
                };
                const nodes = [];
                const makeNode = function (pos, kind) {
                    const node = {
                        id: nodes.length,
                        pos: pos,
                        kind: kind,
                        color: (kind === 'hub' ? C[2] : C[3]).clone().lerp(new THREE.Color(0xffffff), 0.25),
                        phase: Math.random()
                    };
                    nodes.push(node);
                    return node;
                };

                const hubs = [];
                const hubCount = randInt(cfg.hubCount);
                for (let guard = 0; hubs.length < hubCount && guard < 300; guard++) {
                    const p = new THREE.Vector3(
                        portfolioCenter.x + rand(-1, 1) * space.x,
                        portfolioCenter.y + rand(-1, 1) * space.y,
                        portfolioCenter.z + rand(-1, 1) * space.z
                    );
                    if (hubs.every(function (h) { return h.pos.distanceTo(p) >= cfg.hubMinDistance; })) {
                        hubs.push(makeNode(p, 'hub'));
                    }
                }

                // ---------- 2. edges ----------
                const edges = [];
                const linked = {};   // "a-b" -> true, to avoid duplicate links
                const linkKey = function (a, b) { return Math.min(a.id, b.id) + '-' + Math.max(a.id, b.id); };

                const makeEdge = function (kind, from, to, parent) {
                    const len = from.distanceTo(to);
                    const off1 = randVec(len * 0.22);
                    const off2 = randVec(len * 0.22);
                    const curve = new THREE.CubicBezierCurve3(
                        from.clone(),
                        from.clone().lerp(to, 1 / 3).add(off1),
                        from.clone().lerp(to, 2 / 3).add(off2),
                        to.clone()
                    );
                    const edge = {
                        kind: kind,
                        curve: curve,
                        off1: off1,
                        off2: off2,
                        to: to,
                        tracked: kind === 'primary',
                        // children inherit phase & speed from their parent, so a signal that reaches a hub
                        // continues into the next layer (looks like data travelling through the network)
                        phase: parent ? parent.phase : Math.random(),
                        speed: parent ? parent.speed : rand(cfg.speed[0], cfg.speed[1]),
                        pts: []
                    };
                    for (let k = 0; k <= cfg.divisions; k++) edge.pts.push(new THREE.Vector3());
                    edges.push(edge);
                    return edge;
                };

                // layer 0 -> 1 : stone surface -> hubs (these follow the rotating stone every frame)
                const leaves = [];
                hubs.forEach(function (hub) {
                    const direction = hub.pos.clone().sub(sphere.center).normalize();
                    sourceRaycaster.set(sphere.center, direction);
                    const sourceHits = sourceRaycaster.intersectObject(stone, true);
                    const start = sourceHits.length
                        ? sourceHits[0].point.clone().add(direction.clone().multiplyScalar(0.35))
                        : sphere.center.clone().add(direction.clone().multiplyScalar(sphere.radius * 0.72));

                    const primary = makeEdge('primary', start, hub.pos, null);
                    primary.stone = stone;
                    primary.sourceCenterOffset = sourceCenterOffset.clone();

                    // layer 1 -> 2 : hub -> leaves
                    const leafCount = randInt(cfg.leafPerHub);
                    for (let n = 0; n < leafCount; n++) {
                        const dir = new THREE.Vector3(rand(-1, 1), rand(-1, 1), rand(-1, 1) * 0.5).normalize();
                        const leafPos = clampToSpace(hub.pos.clone().add(dir.multiplyScalar(rand(cfg.leafDistance[0], cfg.leafDistance[1]))));
                        const leaf = makeNode(leafPos, 'leaf');
                        leaves.push(leaf);
                        linked[linkKey(hub, leaf)] = true;
                        makeEdge('secondary', hub.pos, leaf.pos, primary);
                    }
                });

                // cross links between neighbouring nodes -> turns the tree into a mesh
                for (let made = 0, guard = 0; made < cfg.crossLinks && guard < 360; guard++) {
                    const na = nodes[Math.floor(Math.random() * nodes.length)];
                    const nb = nodes[Math.floor(Math.random() * nodes.length)];
                    if (!na || !nb || na === nb || linked[linkKey(na, nb)]) continue;
                    const dist = na.pos.distanceTo(nb.pos);
                    if (dist < cfg.crossDistance[0] || dist > cfg.crossDistance[1]) continue;
                    linked[linkKey(na, nb)] = true;
                    makeEdge('cross', na.pos, nb.pos, null);
                    made++;
                }

                // ---------- 3. one geometry for all edges ----------
                const D = cfg.divisions;
                const P = D + 1;
                const vertexCount = edges.length * P * 2;
                const positions = new Float32Array(vertexCount * 3);
                const tangents  = new Float32Array(vertexCount * 3);
                const colors    = new Float32Array(vertexCount * 3);
                const sides     = new Float32Array(vertexCount);
                const progs     = new Float32Array(vertexCount);
                const params    = new Float32Array(vertexCount * 4);
                const indices   = new Uint16Array(edges.length * D * 6);

                // fills positions + tangents of one edge from its curve
                const sampleEdge = function (edge) {
                    for (let j = 0; j <= D; j++) edge.pts[j].copy(edge.curve.getPoint(j / D));
                    for (let j = 0; j <= D; j++) {
                        const prev = edge.pts[Math.max(j - 1, 0)];
                        const next = edge.pts[Math.min(j + 1, D)];
                        const tx = next.x - prev.x, ty = next.y - prev.y, tz = next.z - prev.z;
                        const tl = Math.sqrt(tx * tx + ty * ty + tz * tz) || 1;
                        const p = edge.pts[j];
                        for (let s = 0; s < 2; s++) {
                            const o = (edge.vertexOffset + j * 2 + s) * 3;
                            positions[o] = p.x; positions[o + 1] = p.y; positions[o + 2] = p.z;
                            tangents[o] = tx / tl; tangents[o + 1] = ty / tl; tangents[o + 2] = tz / tl;
                        }
                    }
                };

                edges.forEach(function (edge, e) {
                    edge.vertexOffset = e * P * 2;
                    const width = cfg.widthPx[edge.kind];
                    const boost = cfg.boost[edge.kind];
                    for (let j = 0; j <= D; j++) {
                        const color = sampleGradient(gradients[edge.kind], j / D);
                        for (let s = 0; s < 2; s++) {
                            const v = edge.vertexOffset + j * 2 + s;
                            colors[v * 3] = color.r; colors[v * 3 + 1] = color.g; colors[v * 3 + 2] = color.b;
                            sides[v] = s === 0 ? -1 : 1;
                            progs[v] = j / D;
                            params[v * 4] = edge.phase;
                            params[v * 4 + 1] = edge.speed;
                            params[v * 4 + 2] = width;
                            params[v * 4 + 3] = boost;
                        }
                    }
                    for (let j = 0; j < D; j++) {
                        const a0 = edge.vertexOffset + j * 2;
                        const i = (e * D + j) * 6;
                        indices[i] = a0;     indices[i + 1] = a0 + 1; indices[i + 2] = a0 + 2;
                        indices[i + 3] = a0 + 1; indices[i + 4] = a0 + 3; indices[i + 5] = a0 + 2;
                    }
                    sampleEdge(edge);
                });

                const addAttr = function (geometry, name, array, size, dynamic) {
                    const attr = new THREE.BufferAttribute(array, size);
                    if (dynamic) {
                        if (attr.setDynamic) attr.setDynamic(true);
                        else if (attr.setUsage && THREE.DynamicDrawUsage) attr.setUsage(THREE.DynamicDrawUsage);
                    }
                    if (geometry.setAttribute) geometry.setAttribute(name, attr);
                    else geometry.addAttribute(name, attr);
                    return attr;
                };

                const lineGeometry = new THREE.BufferGeometry();
                const positionAttr = addAttr(lineGeometry, 'position', positions, 3, true);
                const tangentAttr  = addAttr(lineGeometry, 'aTangent', tangents, 3, true);
                addAttr(lineGeometry, 'aColor', colors, 3, false);
                addAttr(lineGeometry, 'aSide', sides, 1, false);
                addAttr(lineGeometry, 'aProg', progs, 1, false);
                addAttr(lineGeometry, 'aParams', params, 4, false);
                lineGeometry.setIndex(new THREE.BufferAttribute(indices, 1));

                const lineMaterial = new THREE.ShaderMaterial({
                    uniforms: {
                        uTime       : worksEnergyUniforms.uTime,
                        uResolution : worksEnergyUniforms.uResolution,
                        uDepthRef   : worksEnergyUniforms.uDepthRef,
                        uOpacity    : { value: 0 }
                    },
                    vertexShader: worksNetShaders.lineVS,
                    fragmentShader: worksNetShaders.lineFS,
                    transparent: true,
                    depthWrite: false,
                    blending: THREE.AdditiveBlending,
                    side: THREE.DoubleSide
                });
                const lineMesh = new THREE.Mesh(lineGeometry, lineMaterial);
                lineMesh.frustumCulled = false;      // vertices are updated every frame
                worksEnergyGroup.add(lineMesh);

                // ---------- 4. glowing nodes ----------
                const nodePositions = new Float32Array(nodes.length * 3);
                const nodeColors = new Float32Array(nodes.length * 3);
                const nodeSizes = new Float32Array(nodes.length);
                const nodePhases = new Float32Array(nodes.length);
                nodes.forEach(function (node, i) {
                    nodePositions[i * 3] = node.pos.x; nodePositions[i * 3 + 1] = node.pos.y; nodePositions[i * 3 + 2] = node.pos.z;
                    nodeColors[i * 3] = node.color.r; nodeColors[i * 3 + 1] = node.color.g; nodeColors[i * 3 + 2] = node.color.b;
                    nodeSizes[i] = cfg.nodePx[node.kind] * rand(0.85, 1.15);
                    nodePhases[i] = node.phase;
                });
                const nodeGeometry = new THREE.BufferGeometry();
                addAttr(nodeGeometry, 'position', nodePositions, 3, false);
                addAttr(nodeGeometry, 'aColor', nodeColors, 3, false);
                addAttr(nodeGeometry, 'aSize', nodeSizes, 1, false);
                addAttr(nodeGeometry, 'aPhase', nodePhases, 1, false);

                const nodeMaterial = new THREE.ShaderMaterial({
                    uniforms: {
                        uTime     : worksEnergyUniforms.uTime,
                        uDepthRef : worksEnergyUniforms.uDepthRef,
                        uOpacity  : { value: 0 }
                    },
                    vertexShader: worksNetShaders.nodeVS,
                    fragmentShader: worksNetShaders.nodeFS,
                    transparent: true,
                    depthWrite: false,
                    blending: THREE.AdditiveBlending
                });
                const nodePoints = new THREE.Points(nodeGeometry, nodeMaterial);
                nodePoints.frustumCulled = false;
                worksEnergyGroup.add(nodePoints);

                // ---------- 5. state used by updateWorksEnergyConnections ----------
                worksEnergyNet = {
                    positionAttr: positionAttr,
                    tangentAttr: tangentAttr,
                    sampleEdge: sampleEdge,
                    raycaster: sourceRaycaster
                };
                worksEnergyConnections = edges.filter(function (edge) { return edge.tracked; });

                TweenMax.to(lineMaterial.uniforms.uOpacity, 0.6, { value: 1, ease: Power2.easeOut });
                TweenMax.to(nodeMaterial.uniforms.uOpacity, 0.6, { value: 1, delay: 0.15, ease: Power2.easeOut });
            }

            function updateWorksEnergyConnections(currentTime) {
                if (!worksEnergyGroup || !worksEnergyGroup.visible || !worksEnergyNet) return;

                worksEnergyUniforms.uTime.value = currentTime;
                worksEnergyUniforms.uResolution.value.set(renderer.domElement.width, renderer.domElement.height);

                if (!worksEnergyConnections.length) return;

                const net = worksEnergyNet;
                worksEnergyConnections.forEach(function (edge) {
                    // keep the start glued to the visible surface of the rotating stone
                    const center = edge.stone.getWorldPosition(new THREE.Vector3()).add(edge.sourceCenterOffset);
                    const direction = edge.to.pos ? edge.to.pos : edge.to;
                    const dir = direction.clone().sub(center).normalize();
                    net.raycaster.set(center, dir);
                    const hits = net.raycaster.intersectObject(edge.stone, true);
                    const start = hits.length
                        ? hits[0].point.clone().add(dir.clone().multiplyScalar(0.35))
                        : center.clone().add(dir.clone().multiplyScalar(1));

                    const end = edge.curve.v3;
                    edge.curve.v0.copy(start);
                    edge.curve.v1.copy(start).lerp(end, 1 / 3).add(edge.off1);
                    edge.curve.v2.copy(start).lerp(end, 2 / 3).add(edge.off2);
                    net.sampleEdge(edge);
                });
                net.positionAttr.needsUpdate = true;
                net.tangentAttr.needsUpdate = true;
            }

            function hideWorksEnergyConnections() {
                if (!worksEnergyGroup) return;

                const groupToRemove = worksEnergyGroup;
                worksEnergyGroup = null;
                worksEnergyConnections = [];
                worksEnergyNet = null;

                const materials = [];
                groupToRemove.children.forEach(function (child) {
                    if (child.material) materials.push(child.material);
                });

                let remaining = materials.length;
                if (!remaining) {
                    if (groupToRemove.parent) groupToRemove.parent.remove(groupToRemove);
                    return;
                }

                materials.forEach(function (material) {
                    // ShaderMaterials of the network fade through their own "uOpacity" uniform
                    const isShader = !!(material.uniforms && material.uniforms.uOpacity);
                    const fadeVars = isShader ? { value: 0 } : { opacity: 0 };
                    fadeVars.ease = Power2.easeIn;
                    fadeVars.onComplete = function () {
                            remaining--;
                            if (remaining === 0) {
                                groupToRemove.children.forEach(function (child) {
                                    if (child.geometry && child.geometry.dispose) child.geometry.dispose();
                                    if (child.material && child.material.dispose) child.material.dispose();
                                });
                                if (groupToRemove.parent) groupToRemove.parent.remove(groupToRemove);
                            }
                    };
                    TweenMax.to(isShader ? material.uniforms.uOpacity : material, 0.28, fadeVars);
                });
            }

            function animateWorksStoneHover(stone) {
                if (!stone) return;

                stone.userData = stone.userData || {};
                if (!stone.userData.hoverRotation) {
                    stone.userData.hoverRotation = {
                        y: stone.rotation.y,
                        z: stone.rotation.z
                    };
                }

                TweenMax.killTweensOf(stone.scale);
                TweenMax.killTweensOf(stone.rotation);

                TweenMax.to(stone.scale, .55, {
                    x: 195,
                    y: 195,
                    z: 195,
                    ease: Sine.easeInOut,
                    repeat: -1,
                    yoyo: true
                });

                TweenMax.to(stone.rotation, .7, {
                    y: stone.userData.hoverRotation.y + .32,
                    z: stone.userData.hoverRotation.z + .12,
                    ease: Sine.easeInOut,
                    repeat: -1,
                    yoyo: true
                });
            }

            function resetWorksStoneHover(stone) {
                if (!stone) return;

                TweenMax.killTweensOf(stone.scale);
                TweenMax.killTweensOf(stone.rotation);

                TweenMax.to(stone.scale, .3, {
                    x: stone.origData ? stone.origData.sx : 1,
                    y: stone.origData ? stone.origData.sy : 1,
                    z: stone.origData ? stone.origData.sz : 1,
                    ease: Power2.easeOut
                });

                if (stone.userData && stone.userData.hoverRotation) {
                    TweenMax.to(stone.rotation, .3, {
                        y: stone.userData.hoverRotation.y,
                        z: stone.userData.hoverRotation.z,
                        ease: Power2.easeOut
                    });
                }
            }

            function animateNavBallHover(ball) {
                if ( !ball || !ball.origData ) return;

                TweenMax.killTweensOf( ball.scale );
                TweenMax.killTweensOf( ball.rotation );

                if ( ball.userData && ball.userData.navHoverReset ) {
                    ball.userData.navHoverReset.kill();
                    ball.userData.navHoverReset = null;
                }


                // Keep the ball visibly enlarged while it continuously changes shape.
                TweenMax.fromTo( ball.scale, .38, {
                    x: ball.origData.sx * 1.32,
                    y: ball.origData.sy * 1.32,
                    z: ball.origData.sz * 1.32
                }, {
                    x: ball.origData.sx * 1.58,
                    y: ball.origData.sy * .92,
                    z: ball.origData.sz * 1.58,
                    ease: Power2.easeInOut,
                    repeat: -1,
                    yoyo: true
                });

                TweenMax.to( ball.rotation, .48, {
                    z: ball.origData.rz + .14,
                    ease: Sine.easeInOut,
                    repeat: -1,
                    yoyo: true
                });

                // It will automatically return to normal after 3 seconds
                ball.userData = ball.userData || {};

                ball.userData.navHoverReset = TweenMax.delayedCall( 3, function() {
                    resetNavBallHover( ball );
                });                
            }

            function resetNavBallHover(ball) {
                if ( !ball || !ball.origData ) return;

                TweenMax.killTweensOf( ball.scale );
                TweenMax.killTweensOf( ball.rotation );

                TweenMax.to( ball.scale, .25, {
                    x: ball.origData.sx,
                    y: ball.origData.sy,
                    z: ball.origData.sz,
                    ease: Power2.easeOut
                });

                TweenMax.to( ball.rotation, .25, {
                    x: ball.origData.rx,
                    y: ball.origData.ry,
                    z: ball.origData.rz,
                    ease: Power2.easeOut
                });
            }

